// Real aria2 and WinForms against local generated bytes only. No media or browser registration.
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Reflection;
using System.Text;
using System.Threading;
using System.Windows.Forms;
using ShiyingDesktop;

class DetailServer:IDisposable {
    readonly TcpListener listener=new TcpListener(IPAddress.Loopback,0);
    readonly Thread accept;
    readonly byte[] bytes;
    public readonly string Url;
    public bool Ranges=true;
    public string ETag="stable-fixture-v1";
    public int RangeRequests;
    public DetailServer(byte[] data){bytes=data;listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/fixture.bin";accept=new Thread(()=>{while(true)try{var client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(_=>Serve(client));}catch{return;}}){IsBackground=true};accept.Start();}
    void Serve(TcpClient client){using(client)try{using(var stream=client.GetStream()){
        var header=new StringBuilder();int c;while((c=stream.ReadByte())>=0){header.Append((char)c);if(header.ToString().EndsWith("\r\n\r\n"))break;if(header.Length>20000)return;}
        long start=0,end=bytes.Length-1;bool partial=false;foreach(string row in header.ToString().Split('\n'))if(row.StartsWith("Range:",StringComparison.OrdinalIgnoreCase)){Interlocked.Increment(ref RangeRequests);if(Ranges){var range=row.Trim().Split('=')[1].Split('-');start=Int64.Parse(range[0]);if(range[1].Length>0)end=Math.Min(end,Int64.Parse(range[1]));partial=true;}}
        if(bytes.Length==0){byte[] zero=Encoding.ASCII.GetBytes("HTTP/1.1 416 Range Not Satisfiable\r\nContent-Length: 0\r\nContent-Range: bytes */0\r\nConnection: close\r\n\r\n");stream.Write(zero,0,zero.Length);return;}
        string text="HTTP/1.1 "+(partial?"206 Partial Content":"200 OK")+"\r\nContent-Length: "+(end-start+1)+"\r\nConnection: close\r\nETag: \""+ETag+"\"\r\n"+(partial?"Content-Range: bytes "+start+"-"+end+"/"+bytes.Length+"\r\n":"")+"\r\n";
        byte[] response=Encoding.ASCII.GetBytes(text);stream.Write(response,0,response.Length);
        for(long offset=start;offset<=end;offset+=32768){int count=(int)Math.Min(32768,end-offset+1);stream.Write(bytes,(int)offset,count);Thread.Sleep(5);}
    }}catch{} }
    public void Dispose(){listener.Stop();accept.Join(2000);}
}
class DetailsCheck {
    static readonly List<string> checks=new List<string>();
    static void Check(bool condition,string text){if(!condition)throw new Exception(text);checks.Add(text);Console.WriteLine("PASS "+text);}
    static object Field(object target,string name){return target.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(target);}
    static void Capture(Form form,string file){Application.DoEvents();Bounds(form);using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(file);}}
    static void Bounds(Control parent){foreach(Control child in parent.Controls){if(child.Visible&&(child.Left<0||child.Top<0||child.Right>parent.ClientSize.Width+2||child.Bottom>parent.ClientSize.Height+2))throw new Exception("Control bounds: "+child.GetType().Name+" "+child.Text);if(child.Visible)Bounds(child);}}
    static void Wait(Manager manager,Func<bool> done,string text,int seconds=30){var end=DateTime.UtcNow.AddSeconds(seconds);while(!done()&&DateTime.UtcNow<end){manager.Tick();Application.DoEvents();Thread.Sleep(40);}Check(done(),text);}
    static string Digest(byte[] bytes){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
    static void NumericChecks(){
        var values=new Dictionary<string,object>{{"large","9007199254740993"},{"zero",0},{"bad",true},{"null",null},{"nan","NaN"},{"fraction",1234.8}};
        Check(TransferData.Number(values,"large")==9007199254740993L&&TransferData.Number(values,"zero")==0&&TransferData.Number(values,"fraction")==1234,"integer byte precision and explicit zero preserved");
        Check(new[]{"bad","null","nan","absent"}.All(key=>TransferData.Number(values,key)==-1),"missing or malformed telemetry remains unknown");
        var job=new Download{Kind="file",Status="下载中",Transfer=new TransferInfo{Total=250,Completed=150,Speed=10,PieceLength=100,Pieces=3,Bitfield="a0"}};
        var rows=TransferData.Segments(job);Check(rows.Length==3&&rows.Select(r=>r.Length).SequenceEqual(new long[]{100,100,50})&&rows.Select(r=>r.Completed).SequenceEqual(new long[]{100,0,50}),"MSB bit order and short final piece use exact byte lengths");
        Check(TransferData.Remaining(job)=="约 10 秒","remaining time derived from remaining bytes and live speed");job.Transfer.Speed=0;Check(TransferData.Remaining(job)=="计算中","zero speed does not invent a completion time");job.Status="已暂停";Check(TransferData.Remaining(job)=="已暂停","paused task does not display stale ETA");
        job.Transfer.Bitfield="x0";Check(TransferData.Segments(job).Length==0,"invalid piece bitmap never produces simulated progress");job.Transfer.Bitfield="a0";job.Transfer.Pieces=4;Check(TransferData.Segments(job).Length==0,"inconsistent piece count refused");
        job.Transfer.Resume=true;Check(TransferData.ResumeText(job)=="无法安全续传","range support without source version is not resumable assurance");job.ETag="\"source\"";Check(TransferData.ResumeText(job).Contains("支持"),"range and source validator enable guarded resume status");
        var video=new Download{Kind="video",Status="下载中"};TransferData.VideoStatus(video,"{\"downloaded_bytes\":65536,\"total_bytes\":null,\"total_bytes_estimate\":262144,\"speed\":32768,\"eta\":6,\"fragment_index\":2,\"fragment_count\":8,\"vcodec\":\"avc1\",\"acodec\":\"none\"}");
        Check(video.Transfer.Estimated&&video.Transfer.Scope=="当前画面轨"&&video.Progress==25&&video.Transfer.FragmentCount==8&&TransferData.Segments(video).Length==0,"video reports estimated current track and real fragment counter only");
        TransferData.VideoStatus(video,"{\"downloaded_bytes\":1024,\"total_bytes\":8192,\"speed\":null,\"eta\":null,\"vcodec\":\"none\",\"acodec\":\"aac\"}");Check(video.Transfer.Completed==1024&&video.Transfer.Scope=="当前声音轨"&&!video.Transfer.Estimated&&TransferData.Remaining(video)=="计算中","audio track transition replaces prior-track counters");
    }
    [STAThread] static int Main(string[] args){try{
        string report=Path.GetFullPath(args[0]);bool headless=args.Length>1&&args[1]=="--headless";Directory.CreateDirectory(report);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);NumericChecks();
        byte[] bytes=new byte[16*1024*1024];for(int n=0;n<bytes.Length;n++)bytes[n]=(byte)(n%251);
        using(var server=new DetailServer(bytes))using(var manager=new Manager(Path.Combine(report,"state"))){
            manager.Config.Folder=Path.Combine(report,"files");manager.Config.Proxy="";manager.Config.Connections=4;manager.Config.RateKiB=1024;
            var job=manager.Add(server.Url,"file","本地字节样例.bin");Wait(manager,()=>job.Transfer.Completed>4194304&&job.Transfer.Speed>0&&TransferData.Segments(job).Sum(r=>r.Completed)>0,"real aria2 counters, speed and completed blocks arrive");
            Check(job.Transfer.Total==bytes.Length&&job.Transfer.Resume==true&&TransferData.Segments(job).Length>0,"real Range probe, total size and aria2 piece map reach download state");
            Check(TransferData.Segments(job).Sum(r=>r.Completed)<=job.Transfer.Completed,"piece totals do not inflate uncompleted block bytes");
            if(headless){manager.Pause(job.Id);Wait(manager,()=>job.Status=="已暂停","headless HTTP pause preserves a real task");manager.Config.RateKiB=0;manager.Resume(job.Id);Wait(manager,()=>job.Status=="已完成","headless HTTP resume finishes generated bytes");Check(ComponentStore.Hash(job.File)==Digest(bytes)&&job.Transfer.Completed==bytes.Length&&TransferData.Segments(job).All(s=>s.Completed==s.Length),"headless HTTP file SHA256 and piece totals agree");}
            else using(var main=new MainWindow(manager,true)){
                main.Show();Application.DoEvents();var grid=(DataGridView)Field(main,"grid");var doubleClick=typeof(DataGridView).GetMethod("OnCellDoubleClick",BindingFlags.NonPublic|BindingFlags.Instance);doubleClick.Invoke(grid,new object[]{new DataGridViewCellEventArgs(0,0)});Application.DoEvents();
                var window=main.OwnedForms.OfType<DownloadDetailsWindow>().Single();doubleClick.Invoke(grid,new object[]{new DataGridViewCellEventArgs(1,0)});Check(main.OwnedForms.OfType<DownloadDetailsWindow>().Count()==1,"double-click opens one modeless detail window per task");
                window.RefreshInfo();var labels=(Label[])Field(window,"values");Check(labels[0].Text=="16 MiB"&&labels[1].Text!="未知"&&labels[3].Text.Contains("约"),"detail labels display real engine values");
                Capture(window,Path.Combine(report,"details-active-100.png"));window.Scale(new SizeF(1.25f,1.25f));Capture(window,Path.Combine(report,"details-active-125.png"));window.Scale(new SizeF(1.2f,1.2f));Capture(window,Path.Combine(report,"details-active-150.png"));
                ((Button)Field(window,"pause")).PerformClick();Wait(manager,()=>job.Status=="已暂停","pause button controls the actual aria2 task");window.RefreshInfo();Check(labels[2].Text=="—"&&labels[3].Text=="已暂停","paused details hide stale speed and time");Capture(window,Path.Combine(report,"details-paused.png"));
                manager.Config.RateKiB=0;((Button)Field(window,"resume")).PerformClick();Wait(manager,()=>job.Status=="已完成","resume button completes local byte fixture");window.RefreshInfo();
                Check(job.Transfer.Completed==bytes.Length&&job.Transfer.Total==bytes.Length&&TransferData.Segments(job).All(row=>row.Completed==row.Length)&&ComponentStore.Hash(job.File)==Digest(bytes),"finished bytes, all piece groups and final SHA256 agree");Check(server.RangeRequests>2,"real resume issued Range requests");Capture(window,Path.Combine(report,"details-completed.png"));window.Close();
                var unknown=manager.Add("https://example.test/"+new string('a',1500),"file","未知大小_"+new string('长',120)+".bin");unknown.Status="已暂停";typeof(Manager).GetMethod("PublishSnapshot",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(manager,null);
                using(var unknownWindow=new DownloadDetailsWindow(manager,unknown.Id)){unknownWindow.Show(main);unknownWindow.RefreshInfo();var unknownLabels=(Label[])Field(unknownWindow,"values");Check(unknownLabels[0].Text=="未知"&&unknownLabels[1].Text=="未知"&&((DataGridView)Field(unknownWindow,"grid")).Rows.Count==0,"unknown and legacy tasks do not display fake sizes or segments");unknownWindow.ClientSize=new Size(784,641);Capture(unknownWindow,Path.Combine(report,"details-long-url-minimum.png"));unknownWindow.Close();}
                var video=manager.Add("https://example.test/fixture.mpd","video","视频界面样例.mp4");video.Status="已暂停";TransferData.VideoStatus(video,"{\"downloaded_bytes\":1048576,\"total_bytes_estimate\":4194304,\"speed\":1000,\"eta\":3000,\"fragment_index\":3,\"fragment_count\":12,\"vcodec\":\"avc1\",\"acodec\":\"none\"}");typeof(Manager).GetMethod("PublishSnapshot",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(manager,null);
                using(var videoWindow=new DownloadDetailsWindow(manager,video.Id)){videoWindow.Show(main);Check(((Label)Field(videoWindow,"state")).Text=="已暂停","paused video does not retain a contradictory downloading status");Capture(videoWindow,Path.Combine(report,"details-video-scope.png"));videoWindow.Close();}main.Close();
            }
            var probeJob=new Download{Url=server.Url};var method=typeof(Manager).GetMethod("Metadata",BindingFlags.NonPublic|BindingFlags.Instance);
            foreach(bool range in new[]{true,false}){
                server.Ranges=range;server.ETag="stable-fixture-v2";var rejected=manager.Add(server.Url,"file",range?"changed.bin":"range-disabled.bin");rejected.HasMetadata=true;rejected.ETag="\"stable-fixture-v1\"";rejected.ExpectedSize=bytes.Length;string partial=Path.Combine(manager.Work(rejected),"payload.download");Directory.CreateDirectory(manager.Work(rejected));File.WriteAllText(partial,"keep partial");File.WriteAllText(partial+".aria2","keep control");manager.Tick();Check(rejected.Status=="失败"&&File.ReadAllText(partial)=="keep partial"&&File.ReadAllText(partial+".aria2")=="keep control",range?"changed source refuses resume and keeps partial data":"non-range source refuses unsafe resume and keeps partial data");
            }
            var metadata=method.Invoke(manager,new object[]{probeJob});Check((bool?)metadata.GetType().GetField("Resume").GetValue(metadata)==false,"server ignoring Range is explicitly non-resumable");
            using(var zero=new DetailServer(new byte[0])){var zeroMeta=method.Invoke(manager,new object[]{new Download{Url=zero.Url}});Check((long)zeroMeta.GetType().GetField("Size").GetValue(zeroMeta)==0,"empty file Range rejection is retained as an explicit zero size");}
        }
        Util.Atomic(Path.Combine(report,"summary.json"),new{ok=true,method=headless?"real aria2 against local generated bytes; HTTP pause/resume, SHA256 and telemetry fixtures; no windows shown, browser, registry or media downloads":"real aria2 against 16 MiB local generated bytes; actual WinForms double-click and pause/resume buttons; current-track video JSON fixtures only; no media downloads, browser or registry changes",checks=checks.ToArray()});Console.WriteLine("DETAIL CHECKS PASSED "+report);return 0;
    }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
